-- ============================================
-- LUMA — Import des 36 fiches de grammaire libre
-- Généré automatiquement depuis les documents déjà rédigés
-- ============================================

with lang as (select id from languages where code = 'en')
insert into grammar_fiches (language_id, cecr_level, position, title, content)
select lang.id, v.cecr_level, v.position, v.title, v.content::jsonb from lang, (values
  ('A1', 1, 'Le verbe *to be*', '{"sections": [{"heading": "Conjugaison complète", "text": "| Personne | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I | I am (I''m) | I am not (I''m not) | Am I…? |\n| You | You are (you''re) | You are not (you aren''t / you''re not) | Are you…? |\n| He/She/It | He is (he''s) | He is not (he isn''t / he''s not) | Is he…? |\n| We | We are (we''re) | We are not (we aren''t) | Are we…? |\n| They | They are (they''re) | They are not (they aren''t) | Are they…? |"}, {"heading": "Exceptions et cas particuliers", "text": "- Pas de contraction négative pour *I am not* → jamais *\"I amn''t\"*, seulement *I''m not*\n- À la forme courte interrogative-négative : *aren''t you?*, *isn''t he?* (utilisé dans les question tags)"}, {"heading": "Pièges fréquents des francophones", "text": "- Oublier le verbe *to be* devant un adjectif : en français \"j''ai 20 ans\" utilise *avoir*, en anglais c''est *to be* → *I am 20 years old*, jamais *I have 20 years*\n- Confondre *it''s* (contraction de *it is*) et *its* (possessif) — homophones à l''écrit uniquement par erreur d''apostrophe"}, {"heading": "Comparaison avec le français", "text": "Le français utilise parfois *avoir* là où l''anglais utilise systématiquement *to be* : avoir faim (*to be hungry*), avoir chaud (*to be hot*), avoir raison (*to be right*), avoir peur (*to be afraid*). C''est l''erreur numéro un des débutants francophones."}, {"heading": "Banque d''exemples", "text": "1. I am a student. — Je suis étudiant.\n2. She is not tired. — Elle n''est pas fatiguée.\n3. Are you ready? — Tu es prêt ?\n4. We are from France. — Nous sommes de France.\n5. It is cold today. — Il fait froid aujourd''hui.\n6. Is he your brother? — C''est ton frère ?\n7. They aren''t at home. — Ils ne sont pas à la maison.\n8. I''m not sure. — Je ne suis pas sûr.\n9. You are very kind. — Tu es très gentil.\n10. Is it Monday today? — On est lundi aujourd''hui ?\n\n**Notions liées** → Fiche 4 (Have got), Fiche 8 (There is/are)"}]}'),
  ('A1', 2, 'Present simple', '{"sections": [{"heading": "Conjugaison complète", "text": "| Personne | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I/You/We/They | I work | I do not work (don''t) | Do I work? |\n| He/She/It | He works | He does not work (doesn''t) | Does he work? |"}, {"heading": "Règles d''orthographe à la 3e personne du singulier", "text": "- Verbe en -s, -sh, -ch, -x, -o → ajout de *-es* (he watches, she goes)\n- Verbe en consonne + y → *y* devient *ies* (he studies, she tries)\n- Verbe en voyelle + y → ajout simple de *-s* (he plays, she says*—exception de prononciation)"}, {"heading": "Pièges fréquents des francophones", "text": "- Oublier le *-s* à la 3e personne du singulier (erreur la plus commune, même à niveau avancé)\n- Utiliser *do/does* en plus du *-s* par réflexe de négation française : *\"He doesn''t likes\"* est faux, c''est *\"He doesn''t like\"* (le *-s* disparaît avec l''auxiliaire)\n- Traduire littéralement le présent progressif français par le present simple anglais (voir Fiche 5)"}, {"heading": "Comparaison avec le français", "text": "Le français n''a qu''un seul présent (\"je mange\" = *I eat* ou *I am eating*). L''anglais distingue systématiquement l''habitude/vérité générale (present simple) de l''action en cours (present continuous) — c''est une distinction fondamentale à intégrer tôt."}, {"heading": "Banque d''exemples", "text": "1. I work in Paris. — Je travaille à Paris.\n2. She doesn''t eat meat. — Elle ne mange pas de viande.\n3. Do you speak English? — Tu parles anglais ?\n4. He goes to school every day. — Il va à l''école tous les jours.\n5. We don''t watch TV a lot. — On ne regarde pas beaucoup la télé.\n6. Does it rain often here? — Il pleut souvent ici ?\n7. They live in London. — Ils vivent à Londres.\n8. My mother cooks every evening. — Ma mère cuisine tous les soirs.\n9. I don''t like coffee. — Je n''aime pas le café.\n10. Does he play football? — Il joue au foot ?\n\n**Notions liées** → Fiche 5 (Present continuous), Fiche 6-7 (Past simple)"}]}'),
  ('A1', 3, 'Articles, pluriels, *there is/are*', '{"sections": [{"heading": "Les articles", "text": "| Article | Usage | Exemple |\n|---|---|---|\n| a | devant un son consonne, singulier, non défini | a car, a university (son \"you\") |\n| an | devant un son voyelle, singulier, non défini | an apple, an hour (h muet) |\n| the | défini, connu, déjà mentionné | the car (celle dont on parle) |\n| Ø (rien) | généralités, noms indénombrables au sens général | Life is beautiful. |"}, {"heading": "Pluriels", "text": "- Règle générale : ajout de *-s* (cats, books)\n- Mots en -s, -sh, -ch, -x, -z → ajout de *-es* (buses, dishes, boxes)\n- Consonne + y → *y* devient *ies* (city → cities)\n- Pluriels irréguliers à mémoriser : man→men, woman→women, child→children, foot→feet, tooth→teeth, mouse→mice, person→people"}, {"heading": "There is / there are", "text": "- *There is* + singulier ou indénombrable (there is a book, there is water)\n- *There are* + pluriel (there are three books)\n- Forme négative : *there isn''t / there aren''t*\n- Forme interrogative : *is there…? / are there…?*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser *the* pour une généralité comme en français (\"j''aime les chats\" → *I like cats*, PAS *I like the cats* qui signifierait des chats précis)\n- Confondre *there is/are* (existence) et *it is* (identification/description)\n- Oublier *a/an* devant une profession : *I am teacher* est faux, c''est *I am a teacher*"}, {"heading": "Comparaison avec le français", "text": "Le français utilise systématiquement un article devant les noms (\"les chats\", \"l''eau\"), l''anglais l''omet pour les généralités et les indénombrables non spécifiés — c''est une source d''erreur constante par calque direct."}, {"heading": "Banque d''exemples", "text": "1. There is a cat on the sofa. — Il y a un chat sur le canapé.\n2. There are five books on the table. — Il y a cinq livres sur la table.\n3. Is there a supermarket near here? — Il y a un supermarché près d''ici ?\n4. I like dogs. — J''aime les chiens. (généralité, pas d''article)\n5. The dog next door is loud. — Le chien d''à côté est bruyant. (chien précis)\n6. She has three children. — Elle a trois enfants.\n7. There isn''t any milk left. — Il ne reste plus de lait.\n8. He is an engineer. — Il est ingénieur.\n9. There are many people here. — Il y a beaucoup de gens ici.\n10. Are there any questions? — Il y a des questions ?\n\n**Notions liées** → Fiche 1 (to be), Fiche 8 (dénombrable/indénombrable)"}]}'),
  ('A1', 4, 'Possessifs, *have got*, quantificateurs', '{"sections": [{"heading": "Adjectifs et pronoms possessifs", "text": "| Personne | Adjectif possessif | Pronom possessif |\n|---|---|---|\n| I | my | mine |\n| You | your | yours |\n| He | his | his |\n| She | her | hers |\n| It | its | — |\n| We | our | ours |\n| They | their | theirs |"}, {"heading": "Have got", "text": "- Forme britannique courante pour exprimer la possession au présent\n- *I have got* (I''ve got) / *I have not got* (haven''t got) / *Have you got…?*\n- Équivalent américain plus fréquent : *have/has* simple (I have a car)"}, {"heading": "Quantificateurs some/any", "text": "- *Some* : phrases affirmatives, et propositions/offres (Would you like some tea?)\n- *Any* : phrases négatives et questions (I don''t have any money. Do you have any pets?)"}, {"heading": "Pièges fréquents des francophones", "text": "- Confondre *his/her* selon le genre du **possesseur**, pas de l''objet possédé : \"sa voiture\" peut être *his car* ou *her car* selon qui possède, contrairement au français où l''accord se fait avec l''objet\n- Utiliser *some* dans une question qui n''est pas une offre : *\"Do you have some brothers?\"* est peu naturel, on attend *any*"}, {"heading": "Comparaison avec le français", "text": "Le français accorde le possessif avec l''objet possédé (sa voiture = his/her car selon le contexte), l''anglais accorde avec le possesseur — inversion complète de la logique, source d''erreurs récurrentes."}, {"heading": "Banque d''exemples", "text": "1. This is my book. — C''est mon livre.\n2. Is this bag yours? — Ce sac est à toi ?\n3. She loves her job. — Elle aime son travail. (à elle)\n4. He loves his job. — Il aime son travail. (à lui)\n5. I''ve got two sisters. — J''ai deux sœurs.\n6. Have you got a pen? — Tu as un stylo ?\n7. I don''t have any time. — Je n''ai pas de temps.\n8. Would you like some water? — Tu veux de l''eau ?\n9. Their house is beautiful. — Leur maison est belle.\n10. Its color is red. — Sa couleur est rouge. (objet/animal)\n\n**Notions liées** → Fiche 1 (to be), Fiche 8 (dénombrable/indénombrable)"}]}'),
  ('A1', 5, 'Present continuous', '{"sections": [{"heading": "Conjugaison", "text": "| Personne | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I | I am working | I am not working | Am I working? |\n| You/We/They | You are working | You aren''t working | Are you working? |\n| He/She/It | He is working | He isn''t working | Is he working? |"}, {"heading": "Règles de formation du participe présent (-ing)", "text": "- Verbe en -e muet → suppression du -e (make → making)\n- Verbe monosyllabe en consonne-voyelle-consonne → doublement de la consonne finale (run → running, stop → stopping)\n- Verbe en -ie → devient -ying (lie → lying)"}, {"heading": "Usage : present simple vs present continuous", "text": "- Present simple = habitude, vérité générale, routine (I work every day)\n- Present continuous = action en cours au moment où l''on parle, ou action temporaire (I am working right now)"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser le present continuous pour une habitude par calque du français (\"je travaille\" traduit systématiquement par *I am working* même pour une routine)\n- Utiliser le present continuous avec des verbes d''état qui le refusent en anglais standard : *love, know, believe, want, understand* restent au present simple même pour une situation actuelle (*I know the answer*, pas *I am knowing*)"}, {"heading": "Comparaison avec le français", "text": "Le français ne marque pas systématiquement cette distinction (\"je mange\" peut vouloir dire \"je mange en général\" ou \"je suis en train de manger\"), d''où la nécessité d''apprendre à identifier le sens voulu avant de traduire."}, {"heading": "Banque d''exemples", "text": "1. I am reading a book right now. — Je suis en train de lire un livre.\n2. She is not listening to me. — Elle ne m''écoute pas (en ce moment).\n3. What are you doing? — Qu''est-ce que tu fais ?\n4. They are working on a new project this month. — Ils travaillent sur un nouveau projet ce mois-ci.\n5. He is cooking dinner tonight. — Il prépare le dîner ce soir.\n6. I know the answer. — Je connais la réponse. (pas de continuous)\n7. We are meeting them tomorrow. — On les rencontre demain. (futur proche via continuous)\n8. Is it raining outside? — Il pleut dehors ?\n9. I''m not working today. — Je ne travaille pas aujourd''hui.\n10. She is always complaining. — Elle se plaint tout le temps. (agacement, usage idiomatique)\n\n**Notions liées** → Fiche 2 (Present simple)"}]}'),
  ('A1', 6, 'Past simple — verbes réguliers', '{"sections": [{"heading": "Formation", "text": "- Base verbale + *-ed* (work → worked)\n- Verbe en -e muet → ajout de *-d* seulement (like → liked)\n- Consonne + y → *y* devient *ied* (study → studied)\n- Monosyllabe consonne-voyelle-consonne → doublement (stop → stopped)"}, {"heading": "Forme négative et interrogative", "text": "- Utilisation de l''auxiliaire *did* pour tous les sujets, verbe repasse à la base\n- Négatif : *did not (didn''t) + base verbale* (I didn''t work)\n- Interrogatif : *Did + sujet + base verbale?* (Did you work?)\n\n**Prononciation du -ed** (souvent négligée mais essentielle à l''oral)\n- /t/ après consonne sourde (worked, watched)\n- /d/ après consonne sonore ou voyelle (played, opened)\n- /ɪd/ après *t* ou *d* (wanted, needed)"}, {"heading": "Pièges fréquents des francophones", "text": "- Garder le *-ed* à la forme négative/interrogative après *did* : *\"Did you worked?\"* est faux, c''est *\"Did you work?\"*\n- Ignorer la prononciation du -ed, qui n''est jamais \"èd\" en anglais sauf après t/d"}, {"heading": "Comparaison avec le français", "text": "Le français a plusieurs passés (passé composé, imparfait, passé simple) que l''apprenant tente de faire correspondre un par un à l''anglais — mais le past simple couvre à la fois le passé composé et l''imparfait pour une action ponctuelle ou une habitude passée révolue."}, {"heading": "Banque d''exemples", "text": "1. I worked yesterday. — J''ai travaillé hier.\n2. She didn''t call me. — Elle ne m''a pas appelé.\n3. Did you watch the film? — Tu as regardé le film ?\n4. We played football last weekend. — On a joué au foot le week-end dernier.\n5. He studied French for two years. — Il a étudié le français pendant deux ans.\n6. They didn''t like the movie. — Ils n''ont pas aimé le film.\n7. I stopped smoking last year. — J''ai arrêté de fumer l''année dernière.\n8. Did she arrive on time? — Elle est arrivée à l''heure ?\n9. We stayed at a hotel. — On est resté dans un hôtel.\n10. He didn''t finish his homework. — Il n''a pas fini ses devoirs.\n\n**Notions liées** → Fiche 7 (Past simple irréguliers), Fiche 12 (Present perfect, niveau A2)"}]}'),
  ('A1', 7, 'Past simple — verbes irréguliers', '{"sections": [{"heading": "Principe", "text": "Contrairement aux verbes réguliers, les verbes irréguliers ne suivent pas la règle du *-ed* et doivent être mémorisés individuellement (voir le module dédié \"Verbes irréguliers\" pour l''entraînement systématique)."}, {"heading": "Les 20 verbes irréguliers les plus fréquents", "text": "| Base | Past simple | Participe passé | Traduction |\n|---|---|---|---|\n| be | was/were | been | être |\n| have | had | had | avoir |\n| do | did | done | faire |\n| go | went | gone | aller |\n| get | got | got | obtenir |\n| make | made | made | faire/fabriquer |\n| say | said | said | dire |\n| see | saw | seen | voir |\n| know | knew | known | savoir |\n| take | took | taken | prendre |\n| come | came | come | venir |\n| think | thought | thought | penser |\n| give | gave | given | donner |\n| find | found | found | trouver |\n| tell | told | told | dire/raconter |\n| eat | ate | eaten | manger |\n| write | wrote | written | écrire |\n| read | read* | read* | lire (*prononciation change: \"red\"*) |\n| feel | felt | felt | ressentir |\n| leave | left | left | partir/laisser |"}, {"heading": "Pièges fréquents des francophones", "text": "- Régulariser un verbe irrégulier par réflexe (*\"goed\"* au lieu de *\"went\"*)\n- Confondre past simple et participe passé quand ils diffèrent (ex. *saw* vs *seen*) — erreur qui devient critique dès l''apprentissage du present perfect"}, {"heading": "Comparaison avec le français", "text": "Le français a aussi des verbes irréguliers (aller → allé, être → été) mais moins nombreux à ce niveau ; l''anglais en a davantage dans le vocabulaire courant, d''où l''intérêt du module dédié pour la mémorisation intensive."}, {"heading": "Banque d''exemples", "text": "1. I went to the cinema last night. — Je suis allé au cinéma hier soir.\n2. She saw a bear in the forest. — Elle a vu un ours dans la forêt.\n3. We had a great time. — On a passé un bon moment.\n4. He didn''t know the answer. — Il ne connaissait pas la réponse.\n5. They took the train. — Ils ont pris le train.\n6. I made a mistake. — J''ai fait une erreur.\n7. Did you write to her? — Tu lui as écrit ?\n8. We came home late. — On est rentré tard.\n9. She felt sick yesterday. — Elle se sentait malade hier.\n10. I left my keys at home. — J''ai laissé mes clés à la maison.\n\n**Notions liées** → Fiche 6 (Past simple réguliers), Module \"Verbes irréguliers\""}]}'),
  ('A1', 8, 'Dénombrable/indénombrable, quantité, prépositions de lieu', '{"sections": [{"heading": "Dénombrable vs indénombrable", "text": "- Dénombrable : peut être compté, a un pluriel (a book, two books)\n- Indénombrable : substance/concept non comptable, pas de pluriel, pas de *a/an* (water, information, advice, furniture)"}, {"heading": "Quantificateurs selon le type", "text": "| Type | Beaucoup | Peu/Un peu | Combien |\n|---|---|---|---|\n| Dénombrable | many | a few / few | How many? |\n| Indénombrable | much | a little / little | How much? |\n| Les deux | a lot of / lots of | — | — |"}, {"heading": "Nuance few/a few et little/a little", "text": "- *A few / a little* = \"quelques, un peu\" (sens positif, suffisant) : I have a few friends.\n- *Few / little* seul = \"peu de, pas assez\" (sens négatif, insuffisant) : I have few friends. (sous-entendu : c''est peu)"}, {"heading": "Prépositions de lieu de base", "text": "*in* (dans, à l''intérieur), *on* (sur), *at* (à, lieu précis), *under* (sous), *behind* (derrière), *in front of* (devant), *between* (entre), *next to* (à côté de)"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser *many* avec un indénombrable (\"many information\" est faux, c''est \"much information\" ou surtout \"a lot of information\")\n- Confondre *in/at* pour les lieux : *at home, at school* (activité) vs *in the kitchen, in London* (espace physique)"}, {"heading": "Comparaison avec le français", "text": "Le français ne distingue pas grammaticalement dénombrable/indénombrable de la même façon (on peut dire \"beaucoup d''eau\" comme \"beaucoup de livres\"), alors que l''anglais impose un choix de quantificateur différent selon le type de nom — point de vigilance permanent."}, {"heading": "Banque d''exemples", "text": "1. I don''t have much money. — Je n''ai pas beaucoup d''argent.\n2. There are many people here. — Il y a beaucoup de gens ici.\n3. She has a few friends in London. — Elle a quelques amis à Londres.\n4. We have little time left. — Il nous reste peu de temps.\n5. The cat is under the table. — Le chat est sous la table.\n6. I live in London. — J''habite à Londres.\n7. She is at work. — Elle est au travail.\n8. The book is on the shelf. — Le livre est sur l''étagère.\n9. He is standing between the two cars. — Il se tient entre les deux voitures.\n10. There''s a lot of furniture in this room. — Il y a beaucoup de meubles dans cette pièce.\n\n**Notions liées** → Fiche 3 (articles et pluriels)"}]}'),
  ('A2', 9, 'Parler du futur — *going to* / *will*', '{"sections": [{"heading": "Formation", "text": "| Structure | Formation | Usage |\n|---|---|---|\n| *going to* | to be + going to + base verbale | intention, projet déjà décidé, prédiction avec preuve visible |\n| *will* | will + base verbale (tous sujets) | décision spontanée, prédiction sans preuve, promesse, offre |"}, {"heading": "Forme négative et interrogative", "text": "- *going to* : *I am not going to work* / *Are you going to work?*\n- *will* : *I will not (won''t) work* / *Will you work?*"}, {"heading": "Nuance essentielle going to vs will", "text": "- *going to* : \"I''m going to call her\" (décision déjà prise avant de parler)\n- *will* : \"I''ll call her\" (décision prise à l''instant même, en parlant)\n- Prédiction avec preuve : \"Look at those clouds, it''s going to rain\" (going to)\n- Prédiction sans preuve concrète : \"I think it will rain tomorrow\" (will)"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser systématiquement *will* pour tout futur par calque du futur simple français\n- Oublier le *to be* devant *going to* (*\"I going to work\"* est faux)"}, {"heading": "Comparaison avec le français", "text": "Le français a deux futurs (futur proche \"je vais faire\" et futur simple \"je ferai\") qui correspondent assez bien à *going to* et *will*, mais la nuance anglaise repose davantage sur le moment de la décision (avant/pendant qu''on parle) que sur la simple proximité temporelle."}, {"heading": "Banque d''exemples", "text": "1. I''m going to visit my parents this weekend. — Je vais rendre visite à mes parents ce week-end.\n2. I think I''ll call him later. — Je pense que je l''appellerai plus tard.\n3. Are you going to finish this today? — Tu vas finir ça aujourd''hui ?\n4. It''s going to rain, look at the sky. — Il va pleuvoir, regarde le ciel.\n5. I''ll help you with that. — Je vais t''aider avec ça. (offre spontanée)\n6. She''s not going to come to the party. — Elle ne va pas venir à la fête.\n7. Will you marry me? — Tu veux m''épouser ?\n8. We''re going to move to London next year. — On va déménager à Londres l''année prochaine.\n9. I promise I will call you tomorrow. — Je promets que je t''appellerai demain.\n10. What are you going to do this summer? — Qu''est-ce que tu vas faire cet été ?\n\n**Notions liées** → Fiche 2 (Present simple, autre usage possible pour futur programmé comme les horaires)"}]}'),
  ('A2', 10, 'Comparatifs et superlatifs', '{"sections": [{"heading": "Formation des comparatifs", "text": "| Type d''adjectif | Règle | Exemple |\n|---|---|---|\n| Court (1 syllabe) | + *-er* | tall → taller |\n| Court en e muet | + *-r* | nice → nicer |\n| Court CVC | doublement + *-er* | big → bigger |\n| Long (2+ syllabes) | *more* + adjectif | expensive → more expensive |\n| Irrégulier | forme propre | good → better, bad → worse, far → further |"}, {"heading": "Formation des superlatifs", "text": "| Type d''adjectif | Règle | Exemple |\n|---|---|---|\n| Court | *the* + adjectif + *-est* | tall → the tallest |\n| Long | *the most* + adjectif | expensive → the most expensive |\n| Irrégulier | forme propre | good → the best, bad → the worst |\n\n**Structure *as…as***\nÉgalité : *as + adjectif + as* (She is as tall as her brother.)\nNégation : *not as…as* (This film isn''t as good as the book.)"}, {"heading": "Pièges fréquents des francophones", "text": "- Doubler le comparatif : *\"more taller\"* est faux\n- Oublier *the* devant le superlatif (*\"He is tallest\"* est faux, c''est *\"He is the tallest\"*)\n- Confondre adjectifs de 2 syllabes qui suivent la règle courte (happy → happier) — pas de règle 100% fixe, à mémoriser au cas par cas"}, {"heading": "Comparaison avec le français", "text": "Le français utilise systématiquement \"plus…que\" quelle que soit la longueur de l''adjectif, alors que l''anglais distingue formellement adjectifs courts (suffixe) et longs (more/most) — source d''erreur fréquente par simplification excessive."}, {"heading": "Banque d''exemples", "text": "1. She is taller than me. — Elle est plus grande que moi.\n2. This book is more interesting than that one. — Ce livre est plus intéressant que celui-là.\n3. He is the tallest in his class. — Il est le plus grand de sa classe.\n4. This is the most beautiful city I''ve seen. — C''est la plus belle ville que j''ai vue.\n5. My car is as fast as yours. — Ma voiture est aussi rapide que la tienne.\n6. This restaurant isn''t as good as the last one. — Ce restaurant n''est pas aussi bon que le précédent.\n7. It''s getting colder every day. — Il fait de plus en plus froid chaque jour.\n8. This is the worst day of my life. — C''est le pire jour de ma vie.\n9. He runs faster than his brother. — Il court plus vite que son frère.\n10. She is the best student in the school. — C''est la meilleure élève de l''école.\n\n**Notions liées** → Fiche 3 (adjectifs de base)"}]}'),
  ('A2', 11, 'Modaux de base — *can, must, should*', '{"sections": [{"heading": "Tableau des modaux", "text": "| Modal | Sens | Négation | Exemple |\n|---|---|---|---|\n| can | capacité, permission | can''t / cannot | I can swim. |\n| must | obligation forte (interne) | mustn''t (interdiction!) | I must finish this today. |\n| have to | obligation (externe, circonstance) | don''t have to (pas obligé) | I have to work tomorrow. |\n| should | conseil | shouldn''t | You should see a doctor. |"}, {"heading": "Particularité grammaticale des modaux", "text": "- Jamais de *-s* à la 3e personne du singulier (he can, pas *he cans*)\n- Jamais suivis de *to* (she can swim, pas *she can to swim*), sauf *have to*\n- Pas besoin de *do/does* pour la négation ou l''interrogation (can you…?, pas *do you can…?*)"}, {"heading": "Nuance cruciale must vs mustn''t vs don''t have to", "text": "- *must* = obligation\n- *mustn''t* = interdiction (ne pas confondre avec l''absence d''obligation !)\n- *don''t have to* = pas d''obligation, mais autorisé si on veut"}, {"heading": "Pièges fréquents des francophones", "text": "- Traduire \"je ne dois pas\" par *mustn''t* alors que le sens voulu est \"je n''ai pas besoin de\" → confusion classique entre interdiction et absence d''obligation\n- Ajouter *to* après *can/must/should* par réflexe"}, {"heading": "Comparaison avec le français", "text": "Le français utilise un seul verbe \"devoir\" pour obligation interne et externe, l''anglais distingue *must* (obligation ressentie, interne) et *have to* (obligation imposée de l''extérieur)."}, {"heading": "Banque d''exemples", "text": "1. I can speak three languages. — Je parle trois langues.\n2. You mustn''t smoke here. — Il est interdit de fumer ici.\n3. I have to finish this report by Friday. — Je dois finir ce rapport avant vendredi.\n4. You don''t have to come if you''re busy. — Tu n''es pas obligé de venir si tu es occupé.\n5. You should drink more water. — Tu devrais boire plus d''eau.\n6. Can I open the window? — Je peux ouvrir la fenêtre ?\n7. She must be tired after that trip. — Elle doit être fatiguée après ce voyage.\n8. We shouldn''t be late. — On ne devrait pas être en retard.\n9. He can''t drive yet. — Il ne sait pas encore conduire.\n10. Must I answer this question? — Je suis obligé de répondre à cette question ?\n\n**Notions liées** → Fiche 24 (modaux avancés, niveau B1)"}]}'),
  ('A2', 12, 'Present perfect', '{"sections": [{"heading": "Formation", "text": "*have/has* + participe passé (verbe régulier en *-ed*, ou forme irrégulière — voir Fiche 7)\n\n| Sujet | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I/You/We/They | I have worked (I''ve) | I haven''t worked | Have you worked? |\n| He/She/It | He has worked (he''s) | He hasn''t worked | Has he worked? |"}, {"heading": "Usages principaux", "text": "- Expérience de vie sans moment précis : *I have been to Japan.*\n- Action passée avec conséquence sur le présent : *I''ve lost my keys.*\n- Avec *for* (durée) et *since* (point de départ) : *I''ve lived here for 5 years / since 2019.*\n- *Ever/never* pour l''expérience : *Have you ever been to London? / I''ve never seen this film.*"}, {"heading": "Present perfect vs past simple — la distinction clé", "text": "- Present perfect : le moment n''est pas précisé ou reste lié au présent (I have visited Rome.)\n- Past simple : le moment est précisé ou l''action est clairement terminée (I visited Rome in 2019.)\n- Incompatible avec un marqueur temporel précis : *\"I have seen him yesterday\"* est faux, c''est *\"I saw him yesterday\"*"}, {"heading": "Pièges fréquents des francophones", "text": "- Confondre avec le passé composé français qui, lui, s''utilise avec des dates précises\n- Inverser *since* (point de départ) et *for* (durée)"}, {"heading": "Comparaison avec le français", "text": "Le passé composé français (\"j''ai visité Rome en 2019\") s''utilise avec des dates précises sans problème, contrairement au present perfect anglais qui l''interdit formellement."}, {"heading": "Banque d''exemples", "text": "1. I have visited Japan twice. — J''ai visité le Japon deux fois.\n2. She hasn''t finished her homework yet. — Elle n''a pas encore fini ses devoirs.\n3. Have you ever tried sushi? — Tu as déjà essayé les sushis ?\n4. I''ve lived in Paris for ten years. — J''habite à Paris depuis dix ans.\n5. He has worked here since 2018. — Il travaille ici depuis 2018.\n6. We have never seen that movie. — On n''a jamais vu ce film.\n7. Has she arrived yet? — Elle est arrivée ?\n8. I''ve just finished my homework. — Je viens juste de finir mes devoirs.\n9. They haven''t called me back. — Ils ne m''ont pas rappelé.\n10. I saw him yesterday. — Je l''ai vu hier. (past simple, moment précisé)\n\n**Notions liées** → Fiche 6-7 (Past simple), Fiche 17 (Present perfect continuous, niveau B1)"}]}'),
  ('A2', 13, 'Prépositions de temps et de lieu', '{"sections": [{"heading": "Prépositions de temps", "text": "| Préposition | Usage | Exemple |\n|---|---|---|\n| at | heure précise, moments spécifiques | at 6pm, at night, at Christmas |\n| on | jours, dates | on Monday, on July 4th |\n| in | mois, années, saisons, périodes longues | in June, in 2024, in summer, in the morning |"}, {"heading": "Prépositions de lieu (approfondissement)", "text": "| Préposition | Usage | Exemple |\n|---|---|---|\n| at | point précis, adresse | at the bus stop, at 12 Baker Street |\n| in | espace fermé, ville, pays | in the box, in London, in France |\n| on | surface, moyen de transport public | on the table, on the bus |"}, {"heading": "Pièges fréquents des francophones", "text": "- Confondre *in the morning* mais *at night* (exception à retenir)\n- Utiliser *in* pour un point précis au lieu de *at*\n- Choisir une préposition par calque direct du français"}, {"heading": "Comparaison avec le français", "text": "Le français utilise principalement \"à\", \"en\" et \"dans\" de façon plus flexible, alors que l''anglais impose des règles plus strictes selon le type exact de moment ou de lieu."}, {"heading": "Banque d''exemples", "text": "1. I wake up at 7am. — Je me réveille à 7h.\n2. See you on Monday. — À lundi.\n3. My birthday is in June. — Mon anniversaire est en juin.\n4. She works at night. — Elle travaille la nuit.\n5. We met at the airport. — On s''est rencontrés à l''aéroport.\n6. The keys are in the drawer. — Les clés sont dans le tiroir.\n7. I read the news on my phone. — Je lis les infos sur mon téléphone.\n8. He was born in 1995. — Il est né en 1995.\n9. Let''s meet at the entrance. — On se retrouve à l''entrée.\n10. I''ll see you in the morning. — On se voit demain matin.\n\n**Notions liées** → Fiche 8 (prépositions de lieu de base)"}]}'),
  ('A2', 14, 'Adverbes de fréquence et de manière', '{"sections": [{"heading": "Adverbes de fréquence — placement et échelle", "text": "| Adverbe | Fréquence approximative |\n|---|---|\n| always | 100% |\n| usually | ~90% |\n| often | ~70% |\n| sometimes | ~50% |\n| rarely / seldom | ~10% |\n| never | 0% |\n\n**Règle de placement** : entre le sujet et le verbe principal, mais après *to be*.\n- I always drink coffee.\n- She is never late.\n- Avec un modal : après le modal (I can always help you.)"}, {"heading": "Adverbes de manière", "text": "Formation générale : adjectif + *-ly* (quick → quickly, careful → carefully)\n- Adjectif en -y → *-ily* (happy → happily)\n- Adjectif en -le → *-ly* remplace le -e (gentle → gently)\n- Irréguliers : good → well, fast → fast, hard → hard"}, {"heading": "Pièges fréquents des francophones", "text": "- Placer l''adverbe de fréquence en début ou fin de phrase par calque du français\n- Confondre *good* (adjectif) et *well* (adverbe) : *\"He plays good\"* est faux"}, {"heading": "Comparaison avec le français", "text": "Le français place plus librement les adverbes de fréquence, alors que l''anglais impose une position fixe juste avant le verbe principal."}, {"heading": "Banque d''exemples", "text": "1. I always eat breakfast. — Je prends toujours mon petit-déjeuner.\n2. She is usually on time. — Elle est généralement à l''heure.\n3. We sometimes go to the cinema. — On va parfois au cinéma.\n4. He rarely calls me. — Il m''appelle rarement.\n5. I have never been to Australia. — Je ne suis jamais allé en Australie.\n6. She speaks English fluently. — Elle parle anglais couramment.\n7. He drives carefully. — Il conduit prudemment.\n8. They arrived quickly. — Ils sont arrivés rapidement.\n9. She sings really well. — Elle chante vraiment bien.\n10. He can always find a solution. — Il trouve toujours une solution.\n\n**Notions liées** → Fiche 2 (Present simple, contexte d''usage principal)"}]}'),
  ('A2', 15, 'Impératif et suggestions', '{"sections": [{"heading": "L''impératif", "text": "- Affirmatif : base verbale seule, sans sujet (Close the door.)\n- Négatif : *Don''t* + base verbale (Don''t be late.)\n- Forme polie : ajout de *please* (Please sit down. / Sit down, please.)"}, {"heading": "Faire une suggestion", "text": "| Structure | Usage | Exemple |\n|---|---|---|\n| Let''s + base verbale | proposition incluant le locuteur | Let''s go to the beach. |\n| Why don''t we/you + base verbale | suggestion sous forme de question | Why don''t we order pizza? |\n| Shall we + base verbale | proposition polie, surtout UK | Shall we start? |\n| How about + gérondif | suggestion informelle | How about going for a walk? |"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser *let''s* comme s''il ne concernait que le locuteur (alors que *let''s* inclut toujours l''interlocuteur — \"let''s\" = \"let us\")\n- Oublier le gérondif après *how about/what about*"}, {"heading": "Comparaison avec le français", "text": "Le français utilise l''impératif de façon proche de l''anglais, mais les suggestions passent souvent par \"si on...\" + imparfait, une structure sans équivalent direct qu''il faut remplacer par *let''s / why don''t we / how about*."}, {"heading": "Banque d''exemples", "text": "1. Close the window, please. — Ferme la fenêtre, s''il te plaît.\n2. Don''t touch that! — Ne touche pas à ça !\n3. Let''s go to the cinema tonight. — Allons au cinéma ce soir.\n4. Why don''t you call her? — Pourquoi tu ne l''appelles pas ?\n5. Shall we order some food? — On commande à manger ?\n6. How about watching a movie? — Et si on regardait un film ?\n7. Please be quiet. — S''il te plaît, sois silencieux.\n8. Let''s not argue about this. — Ne nous disputons pas à ce sujet.\n9. Turn left at the corner. — Tourne à gauche au coin.\n10. Why don''t we try a different approach? — Pourquoi on n''essaierait pas une approche différente ?\n\n**Notions liées** → Fiche 11 (modaux, pour les suggestions avec *should*)"}]}'),
  ('A2', 16, 'Phrasal verbs courants', '{"sections": [{"heading": "Principe", "text": "Un phrasal verb combine un verbe + une particule (préposition/adverbe), avec un sens souvent différent du verbe seul. Essentiel à l''oral, très fréquent dans l''anglais courant."}, {"heading": "20 phrasal verbs essentiels du quotidien", "text": "| Phrasal verb | Sens | Exemple |\n|---|---|---|\n| get up | se lever | I get up at 7am. |\n| wake up | se réveiller | I woke up early today. |\n| turn on/off | allumer/éteindre | Turn off the light. |\n| look for | chercher | I''m looking for my keys. |\n| look after | s''occuper de | She looks after her sister. |\n| give up | abandonner | Don''t give up! |\n| find out | découvrir | I found out the truth. |\n| put on | mettre (vêtement) | Put on your coat. |\n| take off | enlever / décoller (avion) | Take off your shoes. |\n| come back | revenir | He''ll come back tomorrow. |\n| go on | continuer | Please, go on. |\n| fill in/out | remplir (formulaire) | Fill in this form. |\n| pick up | ramasser / récupérer qqn | I''ll pick you up at 8. |\n| set up | organiser, installer | We set up the tent. |\n| break down | tomber en panne | My car broke down. |\n| carry on | continuer | Carry on, don''t stop. |\n| get on/off | monter/descendre (véhicule) | Get on the bus. |\n| run out of | manquer de | We ran out of milk. |\n| hang out | traîner, passer du temps | We hung out yesterday. |\n| check in/out | s''enregistrer/quitter (hôtel) | We checked in at noon. |"}, {"heading": "Séparable ou non séparable", "text": "- Séparables : l''objet peut se placer entre le verbe et la particule, et doit s''y placer si c''est un pronom : *turn it off*, pas *turn off it*\n- Non séparables : l''objet reste toujours après (look after her, jamais *look her after*)"}, {"heading": "Pièges fréquents des francophones", "text": "- Traduire littéralement au lieu d''apprendre l''expression comme un bloc\n- Mal placer le pronom avec les verbes séparables"}, {"heading": "Comparaison avec le français", "text": "Le français n''a pas d''équivalent structurel direct — un seul verbe traduit souvent tout le phrasal verb (get up = se lever). L''apprentissage repose davantage sur la mémorisation par blocs que sur une logique grammaticale transférable."}, {"heading": "Banque d''exemples", "text": "1. I get up at 6:30 every morning. — Je me lève à 6h30 tous les matins.\n2. Can you turn off the TV? — Tu peux éteindre la télé ?\n3. I''m looking for a new job. — Je cherche un nouveau travail.\n4. She looks after her grandmother. — Elle s''occupe de sa grand-mère.\n5. Don''t give up on your dreams. — N''abandonne pas tes rêves.\n6. I need to fill in this form. — Je dois remplir ce formulaire.\n7. Can you pick me up at 5? — Tu peux venir me chercher à 17h ?\n8. We ran out of coffee. — On n''a plus de café.\n9. What time do we check out? — On quitte l''hôtel à quelle heure ?\n10. I found out he was lying. — J''ai découvert qu''il mentait.\n\n**Notions liées** → Fiche 29 (phrasal verbs avancés, niveau B2)"}]}'),
  ('B1', 17, 'Present perfect continuous', '{"sections": [{"heading": "Formation", "text": "*have/has been* + verbe en *-ing*\n\n| Sujet | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I/You/We/They | I have been working | I haven''t been working | Have you been working? |\n| He/She/It | He has been working | He hasn''t been working | Has he been working? |"}, {"heading": "Usage", "text": "- Met l''accent sur la **durée** et le caractère **continu/récent** d''une action, souvent encore en cours ou dont les effets sont visibles\n- *I''ve been waiting for an hour.* (j''attends encore, ou je viens juste de finir d''attendre)\n- Avec *for/since* comme le present perfect simple"}, {"heading": "Present perfect simple vs continuous", "text": "- Simple : résultat, action terminée, quantité (I''ve written three emails.)\n- Continuous : durée, processus, activité récente visible dans ses effets (I''ve been writing emails all morning — d''où ma fatigue.)\n- Avec des verbes d''état (know, believe, own), seul le simple est possible : *I''ve known her for years*, jamais *I''ve been knowing*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser le continuous avec des verbes d''état interdits (comme en Fiche 5 pour le present continuous)\n- Confondre avec le simple quand l''accent est sur le résultat plutôt que la durée"}, {"heading": "Comparaison avec le français", "text": "Le français utilise \"je fais X depuis...\" pour les deux nuances sans distinction grammaticale, l''anglais impose de choisir simple ou continuous selon qu''on insiste sur le résultat ou sur le processus."}, {"heading": "Banque d''exemples", "text": "1. I''ve been studying English for three years. — J''étudie l''anglais depuis trois ans.\n2. She''s been crying, her eyes are red. — Elle a pleuré, ses yeux sont rouges.\n3. Have you been waiting long? — Tu attends depuis longtemps ?\n4. We''ve been working on this project since March. — On travaille sur ce projet depuis mars.\n5. It''s been raining all day. — Il pleut depuis ce matin.\n6. He hasn''t been sleeping well lately. — Il ne dort pas bien ces derniers temps.\n7. I''ve been thinking about you. — J''ai pensé à toi.\n8. They''ve been living here for six months. — Ils vivent ici depuis six mois.\n9. Why are you out of breath? — I''ve been running. — Pourquoi tu es essoufflé ? — J''ai couru.\n10. I''ve written five reports this week. — J''ai écrit cinq rapports cette semaine. (simple, résultat quantifié)\n\n**Notions liées** → Fiche 12 (Present perfect simple)"}]}'),
  ('B1', 18, 'Past continuous vs past simple', '{"sections": [{"heading": "Formation du past continuous", "text": "*was/were* + verbe en *-ing*\n\n| Sujet | Affirmatif | Négatif | Interrogatif |\n|---|---|---|---|\n| I/He/She/It | I was working | I wasn''t working | Was I working? |\n| You/We/They | You were working | You weren''t working | Were you working? |"}, {"heading": "Usage", "text": "- Action en cours à un moment précis du passé, souvent interrompue par une autre action\n- Structure classique : *when + past simple, past continuous* (l''action longue est interrompue par l''action courte)\n- Deux actions parallèles : *while + past continuous, past continuous*"}, {"heading": "Connecteurs narratifs clés", "text": "- *while* : pendant que (deux actions simultanées)\n- *when* : quand (action ponctuelle qui interrompt)\n- *as soon as* : dès que\n- *as* : alors que (simultanéité, ton plus littéraire)"}, {"heading": "Pièges fréquents des francophones", "text": "- Confondre avec l''imparfait français qui a un usage plus large (le past continuous anglais est réservé à l''action en cours interrompue, pas à toute description habituelle du passé, qui relève du past simple ou de *used to*)\n- Utiliser le past continuous pour une série d''actions successives (qui relèvent du past simple)"}, {"heading": "Comparaison avec le français", "text": "L''imparfait français sert à la fois pour \"j''étais en train de\" (past continuous) et pour les habitudes passées (\"je mangeais tous les jours\" = past simple ou *used to* en anglais) — distinction absente en français, source de confusion."}, {"heading": "Banque d''exemples", "text": "1. I was watching TV when she called. — Je regardais la télé quand elle a appelé.\n2. While I was cooking, he was setting the table. — Pendant que je cuisinais, il mettait la table.\n3. What were you doing at 8pm last night? — Qu''est-ce que tu faisais à 20h hier soir ?\n4. She was walking home when it started to rain. — Elle rentrait chez elle à pied quand il a commencé à pleuvoir.\n5. They weren''t listening when the teacher explained it. — Ils n''écoutaient pas quand le professeur l''a expliqué.\n6. As I was leaving, the phone rang. — Alors que je partais, le téléphone a sonné.\n7. I broke my leg while I was skiing. — Je me suis cassé la jambe en skiant.\n8. We were having dinner when the power went out. — On dînait quand le courant a coupé.\n9. He was driving too fast when the accident happened. — Il conduisait trop vite quand l''accident est arrivé.\n10. I ate breakfast, got dressed, and left. — J''ai mangé, je me suis habillé, et je suis parti. (past simple, actions successives)\n\n**Notions liées** → Fiche 6-7 (Past simple)"}]}'),
  ('B1', 19, 'Conditionnels — first & second', '{"sections": [{"heading": "First conditional (probable)", "text": "*If + present simple, ... will + base verbale*\n- Exprime une condition réaliste, probable dans le futur\n- *If it rains, I will stay home.*"}, {"heading": "Second conditional (hypothétique/irréel présent)", "text": "*If + past simple, ... would + base verbale*\n- Exprime une hypothèse irréelle ou peu probable dans le présent/futur\n- *If I won the lottery, I would travel the world.*\n- Particularité : *were* remplace souvent *was* pour tous les sujets dans le style soigné (*If I were you...*)"}, {"heading": "Comparaison first vs second", "text": "- First : *If I have time, I will call you.* (c''est probable, réaliste)\n- Second : *If I had more time, I would call you.* (moins probable, ou contraire à la réalité présente)"}, {"heading": "Pièges fréquents des francophones", "text": "- Mettre *will* après *if* dans le first conditional (*\"If it will rain\"* est faux, c''est *\"If it rains\"*)\n- Utiliser *would* dans les deux parties de la phrase (*\"If I would have time\"* est faux, la partie *if* reste au past simple)\n- Confondre avec le conditionnel français qui s''utilise différemment selon les propositions"}, {"heading": "Comparaison avec le français", "text": "Le français utilise \"si + présent, futur\" (first) et \"si + imparfait, conditionnel\" (second) — la structure est assez proche, MAIS l''erreur de mettre *would* après *if* vient souvent d''une confusion avec le conditionnel français qui, lui, peut apparaître des deux côtés dans certains registres oraux fautifs."}, {"heading": "Banque d''exemples", "text": "1. If it rains tomorrow, I will stay home. — S''il pleut demain, je resterai à la maison.\n2. If you study hard, you will pass the exam. — Si tu étudies bien, tu réussiras l''examen.\n3. If I had a million euros, I would buy a house. — Si j''avais un million d''euros, j''achèterais une maison.\n4. If I were you, I would apologize. — À ta place, je m''excuserais.\n5. What would you do if you lost your job? — Que ferais-tu si tu perdais ton emploi ?\n6. If she calls, tell her I''m busy. — Si elle appelle, dis-lui que je suis occupé.\n7. I would travel more if I had more money. — Je voyagerais plus si j''avais plus d''argent.\n8. If we leave now, we will arrive on time. — Si on part maintenant, on arrivera à l''heure.\n9. If he studied more, he would get better grades. — S''il étudiait plus, il aurait de meilleures notes.\n10. If you don''t hurry, you will miss the train. — Si tu ne te dépêches pas, tu vas rater le train.\n\n**Notions liées** → Fiche 25 (third conditional et mixed, niveau B2)"}]}'),
  ('B1', 20, 'La voix passive (présent et passé)', '{"sections": [{"heading": "Formation", "text": "sujet + *to be* (au temps voulu) + participe passé + *(by + agent, facultatif)*\n\n| Temps | Actif | Passif |\n|---|---|---|\n| Present simple | They make cars. | Cars are made. |\n| Past simple | They made cars. | Cars were made. |\n| Present continuous | They are making a car. | A car is being made. |\n| Present perfect | They have made a car. | A car has been made. |"}, {"heading": "Usage", "text": "- Quand l''agent est inconnu, évident, ou sans importance : *My car was stolen.* (on ne sait pas qui)\n- Registre plus formel/journalistique : *The decision was made yesterday.*\n- Mentionner l''agent seulement si pertinent : *The Mona Lisa was painted by Leonardo da Vinci.*"}, {"heading": "Pièges fréquents des francophones", "text": "- Oublier de conjuguer *to be* au bon temps (garder systématiquement *is/are* même au passé)\n- Utiliser le passif à outrance par calque d''un français plus neutre — l''anglais courant préfère souvent l''actif quand l''agent est connu et pertinent"}, {"heading": "Comparaison avec le français", "text": "Le français utilise aussi la voix passive avec \"être\" + participe passé de façon très similaire structurellement, ce qui facilite la transposition, mais le français a aussi le pronom \"on\" comme alternative très fréquente (\"on a construit ce pont en 1990\"), moins disponible en anglais où le passif est alors préféré."}, {"heading": "Banque d''exemples", "text": "1. English is spoken all over the world. — L''anglais est parlé partout dans le monde.\n2. This house was built in 1920. — Cette maison a été construite en 1920.\n3. My phone was stolen yesterday. — Mon téléphone a été volé hier.\n4. The meeting has been cancelled. — La réunion a été annulée.\n5. The Eiffel Tower was designed by Gustave Eiffel. — La tour Eiffel a été conçue par Gustave Eiffel.\n6. Breakfast is served from 7 to 10am. — Le petit-déjeuner est servi de 7h à 10h.\n7. The report is being reviewed at the moment. — Le rapport est en cours de révision.\n8. Mistakes were made. — Des erreurs ont été commises.\n9. The letter was sent last week. — La lettre a été envoyée la semaine dernière.\n10. New rules have been introduced. — De nouvelles règles ont été introduites.\n\n**Notions liées** → Fiche 27 (passif avancé, niveau B2)"}]}'),
  ('B1', 21, 'Discours rapporté (affirmations et questions)', '{"sections": [{"heading": "Transformation des temps (backshift)", "text": "| Discours direct | Discours rapporté |\n|---|---|\n| present simple | past simple |\n| present continuous | past continuous |\n| past simple | past perfect |\n| present perfect | past perfect |\n| will | would |\n| can | could |"}, {"heading": "Affirmations rapportées", "text": "- *She said, \"I am tired.\"* → *She said (that) she was tired.*\n- Changement des pronoms et des repères temporels/spatiaux : *today → that day*, *tomorrow → the next day*, *here → there*"}, {"heading": "Questions rapportées", "text": "- Question fermée : *\"Are you coming?\"* → *He asked if/whether I was coming.* (pas d''inversion, pas de point d''interrogation)\n- Question ouverte : *\"Where do you live?\"* → *He asked where I lived.* (mot interrogatif conservé, ordre sujet-verbe rétabli)"}, {"heading": "Pièges fréquents des francophones", "text": "- Garder l''inversion sujet-verbe dans la question rapportée (*\"He asked where did I live\"* est faux)\n- Oublier *if/whether* pour les questions fermées\n- Ne pas reculer les temps (backshift) systématiquement"}, {"heading": "Comparaison avec le français", "text": "Le français opère une transformation similaire (\"il a dit qu''il était fatigué\") mais sans backshift systématique aussi strict, et sans devoir rétablir l''ordre sujet-verbe dans les questions rapportées de la même façon."}, {"heading": "Banque d''exemples", "text": "1. \"I am happy,\" she said. → She said she was happy. — Elle a dit qu''elle était heureuse.\n2. \"I will call you,\" he said. → He said he would call me. — Il a dit qu''il m''appellerait.\n3. \"I have finished,\" she said. → She said she had finished. — Elle a dit qu''elle avait fini.\n4. \"Are you coming?\" he asked. → He asked if I was coming. — Il a demandé si je venais.\n5. \"Where do you work?\" she asked. → She asked where I worked. — Elle a demandé où je travaillais.\n6. \"I can help you,\" he said. → He said he could help me. — Il a dit qu''il pouvait m''aider.\n7. \"Do you like coffee?\" she asked. → She asked if I liked coffee. — Elle a demandé si j''aimais le café.\n8. \"I saw him yesterday,\" she said. → She said she had seen him the day before. — Elle a dit qu''elle l''avait vu la veille.\n9. \"What time is it?\" he asked. → He asked what time it was. — Il a demandé quelle heure il était.\n10. \"I''m leaving tomorrow,\" she said. → She said she was leaving the next day. — Elle a dit qu''elle partait le lendemain.\n\n**Notions liées** → Fiche 32 (discours rapporté avancé, niveau C1)"}]}'),
  ('B1', 22, 'Propositions relatives', '{"sections": [{"heading": "Pronoms relatifs", "text": "| Pronom | Usage | Exemple |\n|---|---|---|\n| who | personne, sujet | The man who called is my boss. |\n| which | chose/animal, sujet ou objet | The book which I read was great. |\n| that | personne ou chose (informel, remplace who/which) | The car that I bought is red. |\n| whose | possession | The woman whose car was stolen is here. |\n| where | lieu | The city where I was born is beautiful. |"}, {"heading": "Relatives déterminatives vs non déterminatives", "text": "- Déterminative (essentielle, pas de virgule) : *The book that I bought is on the table.* (précise lequel)\n- Non déterminative (information supplémentaire, entre virgules) : *My mother, who lives in Lyon, is visiting me.* (info en plus, pas essentielle) — *that* impossible ici, uniquement *who/which*"}, {"heading": "Omission du pronom relatif", "text": "Possible quand le pronom est objet dans une relative déterminative : *The book (that) I bought is great.*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser *which* pour une personne (doit être *who* ou *that*)\n- Garder un pronom personnel en plus du relatif (*\"The man who he called me\"* est faux — un seul pronom pour le rôle)\n- Utiliser *that* dans une relative non déterminative (impossible, uniquement who/which après une virgule)"}, {"heading": "Comparaison avec le français", "text": "Le français utilise \"qui/que/dont/où\" avec une logique de fonction grammaticale (sujet/objet/complément) assez proche du système anglais, mais la distinction déterminative/non déterminative avec le choix obligatoire who/which (jamais that) après une virgule est spécifique à l''anglais et n''a pas d''équivalent formel aussi strict en français."}, {"heading": "Banque d''exemples", "text": "1. The man who lives next door is a doctor. — L''homme qui habite à côté est médecin.\n2. This is the book that changed my life. — C''est le livre qui a changé ma vie.\n3. The woman whose dog barks all night is my neighbor. — La femme dont le chien aboie toute la nuit est ma voisine.\n4. This is the restaurant where we met. — C''est le restaurant où on s''est rencontrés.\n5. My brother, who lives in Canada, is coming to visit. — Mon frère, qui vit au Canada, vient nous rendre visite.\n6. The film which won the award was excellent. — Le film qui a gagné le prix était excellent.\n7. The people I work with are very friendly. — Les gens avec qui je travaille sont très sympas. (pronom omis)\n8. Paris, which is the capital of France, is beautiful in spring. — Paris, qui est la capitale de la France, est belle au printemps.\n9. The job that I applied for was already taken. — Le poste pour lequel j''ai postulé était déjà pris.\n10. This is the reason why I called you. — C''est la raison pour laquelle je t''ai appelé.\n\n**Notions liées** → Fiche 33 (phrases clivées, niveau C1)"}]}'),
  ('B1', 23, 'Gérondif vs infinitif', '{"sections": [{"heading": "Verbes suivis du gérondif (-ing)", "text": "enjoy, like, love, hate, finish, avoid, suggest, mind, imagine, keep, consider\n*I enjoy reading. / She finished cooking. / He avoids talking about it.*"}, {"heading": "Verbes suivis de l''infinitif (to + base verbale)", "text": "want, need, decide, plan, hope, promise, agree, refuse, learn, manage\n*I want to leave. / She decided to study. / They agreed to help.*"}, {"heading": "Verbes qui acceptent les deux, avec changement de sens", "text": "- *stop* : *I stopped smoking* (j''ai arrêté de fumer, fin d''une habitude) vs *I stopped to smoke* (je me suis arrêté pour fumer, but de l''arrêt)\n- *remember* : *I remember locking the door* (souvenir d''une action passée) vs *I remembered to lock the door* (ne pas oublier de le faire)\n- *try* : *try doing* (tester une méthode) vs *try to do* (faire un effort pour réussir)"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser systématiquement l''infinitif par calque du français (\"j''aime lire\" → réflexe de dire *I like to read* uniquement, alors que *I like reading* est tout aussi correct et même plus naturel dans beaucoup de contextes)\n- Se tromper sur les verbes à sens variable (stop, remember, try) qui changent totalement de sens"}, {"heading": "Comparaison avec le français", "text": "Le français utilise systématiquement l''infinitif après un verbe conjugué (\"j''aime lire\", \"je veux partir\"), sans distinction structurelle — c''est la source principale de l''erreur des francophones qui plaquent l''infinitif partout en anglais, alors que le choix gérondif/infinitif dépend du verbe précédent et doit être mémorisé cas par cas."}, {"heading": "Banque d''exemples", "text": "1. I enjoy playing tennis. — J''aime jouer au tennis.\n2. She wants to become a doctor. — Elle veut devenir médecin.\n3. We finished eating at 9pm. — On a fini de manger à 21h.\n4. He decided to quit his job. — Il a décidé de démissionner.\n5. I avoid eating sugar. — J''évite de manger du sucre.\n6. They agreed to meet later. — Ils ont accepté de se retrouver plus tard.\n7. I stopped drinking coffee last year. — J''ai arrêté de boire du café l''année dernière.\n8. Don''t forget to call me. — N''oublie pas de m''appeler.\n9. I remember visiting this place as a child. — Je me souviens d''avoir visité cet endroit enfant.\n10. She suggested going for a walk. — Elle a suggéré d''aller se promener.\n\n**Notions liées** → Fiche 2 (Present simple), révision continue nécessaire (liste à mémoriser progressivement)"}]}'),
  ('B1', 24, 'Modaux avancés — déduction et regret passés', '{"sections": [{"heading": "Déduction passée", "text": "| Structure | Sens | Exemple |\n|---|---|---|\n| must have + participe passé | déduction forte, quasi-certaine | She must have left already. |\n| might/could have + participe passé | possibilité, hypothèse | He might have missed the bus. |\n| can''t have + participe passé | déduction négative forte | They can''t have arrived yet. |"}, {"heading": "Regret / reproche passé", "text": "| Structure | Sens | Exemple |\n|---|---|---|\n| should have + participe passé | regret, reproche (aurait dû) | I should have studied more. |\n| shouldn''t have + participe passé | reproche sur une action faite (n''aurait pas dû) | You shouldn''t have said that. |"}, {"heading": "Pièges fréquents des francophones", "text": "- Oublier le participe passé après *have* et utiliser la base verbale (*\"must have leave\"* est faux)\n- Confondre *must have* (déduction) avec une obligation passée (qui n''existe pas sous cette forme — *must* n''a pas de forme passée directe, on utilise *had to*)"}, {"heading": "Comparaison avec le français", "text": "Le français rend ces nuances avec \"il a dû partir\" (déduction) ou \"j''aurais dû étudier\" (regret) — structures conceptuellement proches, mais l''anglais fige la forme *modal + have + participe passé* de façon plus systématique et mécanique."}, {"heading": "Banque d''exemples", "text": "1. She must have forgotten our meeting. — Elle a dû oublier notre rendez-vous.\n2. He might have taken the wrong train. — Il a peut-être pris le mauvais train.\n3. They can''t have finished already, it''s too soon. — Ils n''ont pas pu finir déjà, c''est trop tôt.\n4. I should have called you earlier. — J''aurais dû t''appeler plus tôt.\n5. You shouldn''t have spent all that money. — Tu n''aurais pas dû dépenser tout cet argent.\n6. She could have told me the truth. — Elle aurait pu me dire la vérité.\n7. We must have missed the exit. — On a dû rater la sortie.\n8. He shouldn''t have driven after drinking. — Il n''aurait pas dû conduire après avoir bu.\n9. I might have left my keys at your place. — J''ai peut-être laissé mes clés chez toi.\n10. They should have arrived by now. — Ils devraient déjà être arrivés.\n\n**Notions liées** → Fiche 11 (modaux de base), Fiche 30 (nuances modales, niveau B2)"}]}'),
  ('B2', 25, 'Third conditional et mixed conditionals', '{"sections": [{"heading": "Third conditional (irréel du passé)", "text": "*If + past perfect, ... would have + participe passé*\n- Exprime un regret ou une hypothèse impossible car le passé est révolu\n- *If I had studied harder, I would have passed the exam.* (je n''ai pas étudié, je n''ai pas réussi)"}, {"heading": "Mixed conditionals", "text": "Combinaison de temps différents entre la condition et la conséquence, quand la logique temporelle l''exige :\n- Condition passée → conséquence présente : *If I had taken that job, I would be rich now.*\n- Condition présente/générale → conséquence passée : *If she weren''t so shy, she would have spoken at the meeting.*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser *would have* dans la partie *if* (*\"If I would have known\"* est très fréquent chez les francophones mais faux — la partie *if* reste au past perfect)\n- Ne pas adapter les mixed conditionals à la logique temporelle réelle de la situation, en appliquant mécaniquement le \"vrai\" third conditional partout"}, {"heading": "Comparaison avec le français", "text": "Le français utilise \"si j''avais su, j''aurais...\" avec plus-que-parfait + conditionnel passé — structure très proche du third conditional anglais, ce qui facilite l''apprentissage, mais les mixed conditionals n''ont pas d''équivalent aussi formalisé en français et demandent un vrai travail de logique temporelle."}, {"heading": "Banque d''exemples", "text": "1. If I had known you were coming, I would have cooked more. — Si j''avais su que tu venais, j''aurais cuisiné plus.\n2. She would have passed if she had studied. — Elle aurait réussi si elle avait étudié.\n3. If we had left earlier, we wouldn''t have missed the train. — Si on était partis plus tôt, on n''aurait pas raté le train.\n4. If I hadn''t met her, my life would be different now. — Si je ne l''avais pas rencontrée, ma vie serait différente maintenant. (mixed)\n5. If he weren''t so stubborn, he would have listened to us. — S''il n''était pas si têtu, il nous aurait écoutés. (mixed)\n6. I wouldn''t have called if I had known you were busy. — Je n''aurais pas appelé si j''avais su que tu étais occupé.\n7. If they had invested earlier, they would be millionaires today. — S''ils avaient investi plus tôt, ils seraient millionnaires aujourd''hui. (mixed)\n8. What would you have done in my situation? — Qu''aurais-tu fait à ma place ?\n9. If I had saved more money, I could travel now. — Si j''avais économisé plus, je pourrais voyager maintenant. (mixed)\n10. She wouldn''t have been late if her car hadn''t broken down. — Elle ne serait pas arrivée en retard si sa voiture n''était pas tombée en panne.\n\n**Notions liées** → Fiche 19 (first & second conditional)"}]}'),
  ('B2', 26, 'Past perfect (simple et continuous)', '{"sections": [{"heading": "Past perfect simple", "text": "*had* + participe passé — antériorité par rapport à un autre point du passé\n*When I arrived, she had already left.* (elle était partie avant mon arrivée)"}, {"heading": "Past perfect continuous", "text": "*had been* + verbe en *-ing* — durée avant un point du passé\n*I was tired because I had been working all day.*"}, {"heading": "Usage dans le récit", "text": "Le past perfect permet de \"revenir en arrière\" dans un récit au past simple, pour préciser ce qui s''était passé avant :\n*I felt terrible. I had eaten too much at the party.* (le repas trop copieux a précédé le malaise)\n\n**Connecteurs typiques** : *before, after, already, just, by the time*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser systématiquement le past simple pour tout le passé sans marquer l''antériorité, ce qui rend le récit confus en anglais (contrairement au français qui tolère mieux l''usage du seul passé composé/imparfait pour narrer)\n- Confondre avec le present perfect (le past perfect s''ancre toujours par rapport à un repère passé, pas au présent)"}, {"heading": "Comparaison avec le français", "text": "Le plus-que-parfait français (\"j''avais mangé\") fonctionne de manière très similaire au past perfect anglais — la structure se transpose bien, mais les francophones ont tendance à l''omettre en anglais alors qu''ils l''utiliseraient naturellement en français, par simplification excessive."}, {"heading": "Banque d''exemples", "text": "1. When I got home, they had already eaten dinner. — Quand je suis rentré, ils avaient déjà dîné.\n2. She was exhausted because she had been running for two hours. — Elle était épuisée car elle courait depuis deux heures.\n3. I had never seen snow before I visited Canada. — Je n''avais jamais vu de neige avant de visiter le Canada.\n4. By the time we arrived, the film had already started. — Le temps qu''on arrive, le film avait déjà commencé.\n5. He had finished his homework before dinner. — Il avait fini ses devoirs avant le dîner.\n6. I realized I had forgotten my passport. — J''ai réalisé que j''avais oublié mon passeport.\n7. They had been waiting for an hour when the bus finally arrived. — Ils attendaient depuis une heure quand le bus est enfin arrivé.\n8. She had already left when I called. — Elle était déjà partie quand j''ai appelé.\n9. We had been driving for six hours before we stopped. — On conduisait depuis six heures avant de s''arrêter.\n10. I had just finished my coffee when the phone rang. — Je venais de finir mon café quand le téléphone a sonné.\n\n**Notions liées** → Fiche 6-7 (Past simple), Fiche 17 (Present perfect continuous)"}]}'),
  ('B2', 27, 'Voix passive avancée', '{"sections": [{"heading": "Passif avec modaux", "text": "*modal + be + participe passé*\n*The report must be finished by Friday. / This problem can be solved easily.*"}, {"heading": "Passif avec verbes à deux compléments", "text": "Certains verbes (give, tell, offer, send) permettent deux constructions passives :\n- *They gave her an award.* → *She was given an award.* (sujet = bénéficiaire) OU *An award was given to her.* (sujet = objet donné)\n- La première tournure (bénéficiaire en sujet) est plus naturelle et fréquente à l''oral."}, {"heading": "Passif avec verbes de perception/opinion (structure formelle)", "text": "*It is said that... / It is believed that...* ou *Sujet + is said/believed + to + infinitif*\n- *It is said that he is very rich.* = *He is said to be very rich.*\n- Très utilisé en anglais journalistique et académique pour rapporter une opinion générale sans l''attribuer nommément."}, {"heading": "Pièges fréquents des francophones", "text": "- Ne pas connaître la structure *is said to* / *is believed to*, absente en français sous cette forme et donc jamais spontanément utilisée\n- Mal choisir quel élément mettre en sujet dans les verbes à double complément"}, {"heading": "Comparaison avec le français", "text": "Le français rend \"on dit que...\" par une tournure impersonnelle avec \"on\", alors que l''anglais préfère souvent la structure passive *it is said that* ou *he is said to be* dans un registre plus soutenu — l''anglais journalistique/académique a une vraie préférence pour le passif là où le français reste plus naturellement actif."}, {"heading": "Banque d''exemples", "text": "1. This task must be completed today. — Cette tâche doit être terminée aujourd''hui.\n2. She was given a promotion last month. — Elle a reçu une promotion le mois dernier.\n3. It is said that the company will be sold soon. — On dit que l''entreprise sera bientôt vendue.\n4. He is believed to be hiding somewhere in Europe. — On pense qu''il se cache quelque part en Europe.\n5. The results should be announced tomorrow. — Les résultats devraient être annoncés demain.\n6. I was offered a new position. — On m''a offert un nouveau poste.\n7. The building is thought to be over 200 years old. — On pense que le bâtiment a plus de 200 ans.\n8. This issue can be fixed quickly. — Ce problème peut être résolu rapidement.\n9. Visitors are not allowed to touch the paintings. — Les visiteurs ne sont pas autorisés à toucher les tableaux.\n10. The letter was sent to the wrong address. — La lettre a été envoyée à la mauvaise adresse.\n\n**Notions liées** → Fiche 20 (passif présent/passé)"}]}'),
  ('B2', 28, 'Connecteurs de discours avancés', '{"sections": [{"heading": "Connecteurs d''opposition/concession", "text": "| Connecteur | Registre | Exemple |\n|---|---|---|\n| however | neutre/formel | The plan failed. However, we learned a lot. |\n| nevertheless | formel | The risks were high. Nevertheless, she proceeded. |\n| although / even though | neutre | Although it was raining, we went out. |\n| despite / in spite of | formel (+ nom ou gérondif) | Despite the rain, we went out. |\n| whereas / while | comparaison formelle | She likes tea, whereas he prefers coffee. |"}, {"heading": "Connecteurs de cause/conséquence", "text": "| Connecteur | Usage | Exemple |\n|---|---|---|\n| therefore | conséquence formelle | The results were poor. Therefore, we changed strategy. |\n| as a result | conséquence | It rained heavily. As a result, the match was cancelled. |\n| due to / owing to | cause (+ nom) | The delay was due to bad weather. |\n| since / as | cause (informel) | Since it was late, we left. |"}, {"heading": "Pièges fréquents des francophones", "text": "- Confondre *despite* (+ nom/gérondif) avec *although* (+ proposition complète) : *\"Despite it was raining\"* est faux, c''est *\"Despite the rain\"* ou *\"Although it was raining\"*\n- Utiliser ces connecteurs formels à l''oral informel, ce qui sonne artificiel — registre à adapter au contexte"}, {"heading": "Comparaison avec le français", "text": "Le français dispose d''un éventail similaire (\"cependant, néanmoins, bien que, malgré, en raison de\") avec la même distinction formel/informel, ce qui facilite le transfert conceptuel — la difficulté principale est purement la construction grammaticale qui suit chaque connecteur (nom vs proposition)."}, {"heading": "Banque d''exemples", "text": "1. The exam was difficult. However, most students passed. — L''examen était difficile. Cependant, la plupart des étudiants ont réussi.\n2. Although he was tired, he kept working. — Bien qu''il soit fatigué, il a continué à travailler.\n3. Despite the traffic, we arrived on time. — Malgré les embouteillages, on est arrivés à l''heure.\n4. She prefers the countryside, whereas I prefer the city. — Elle préfère la campagne, alors que je préfère la ville.\n5. The flight was delayed due to a technical issue. — Le vol a été retardé en raison d''un problème technique.\n6. Sales dropped. As a result, the company cut costs. — Les ventes ont chuté. En conséquence, l''entreprise a réduit ses coûts.\n7. Since you''re here, let''s talk. — Puisque tu es là, parlons.\n8. The project failed; nevertheless, it taught us valuable lessons. — Le projet a échoué ; néanmoins, il nous a appris des choses précieuses.\n9. Owing to the strike, trains are cancelled today. — En raison de la grève, les trains sont annulés aujourd''hui.\n10. He is very confident, whereas his brother is quite shy. — Il est très confiant, alors que son frère est plutôt timide.\n\n**Notions liées** → Fiche 36 (fluidité conversationnelle, niveau C1)"}]}'),
  ('B2', 29, 'Phrasal verbs avancés', '{"sections": [{"heading": "20 phrasal verbs de registre soutenu ou nuancé", "text": "| Phrasal verb | Sens | Exemple |\n|---|---|---|\n| bring up | évoquer un sujet / élever un enfant | She brought up an interesting point. |\n| come across | tomber sur, sembler | I came across an old photo. / He comes across as rude. |\n| get away with | s''en sortir sans punition | He got away with lying. |\n| go through | traverser (épreuve), examiner | She''s going through a hard time. |\n| put off | reporter, repousser | We put off the meeting. |\n| turn out | s''avérer | It turned out to be a great idea. |\n| work out | résoudre, s''entraîner, bien se passer | Things worked out fine. |\n| take after | ressembler à (famille) | She takes after her mother. |\n| stand out | se démarquer | Her work really stands out. |\n| fall through | échouer (projet, plan) | The deal fell through. |\n| look into | enquêter sur | We''re looking into the issue. |\n| back up | soutenir, sauvegarder | Can you back up your claim? |\n| carry out | réaliser, exécuter | They carried out the plan. |\n| bring about | provoquer, causer | The reform brought about major changes. |\n| deal with | gérer, traiter | I''ll deal with it tomorrow. |\n| hold on | attendre, tenir bon | Hold on a second. |\n| point out | souligner, faire remarquer | She pointed out a mistake. |\n| set out | entreprendre, partir | He set out to prove his point. |\n| break out | éclater (guerre, incendie) | War broke out in 1939. |\n| wear off | s''estomper, disparaître progressivement | The pain will wear off soon. |"}, {"heading": "Pièges fréquents des francophones", "text": "- Ces phrasal verbs sont souvent polysémiques (plusieurs sens selon le contexte) : *come across* signifie \"tomber sur\" mais aussi \"paraître, donner l''impression de\" — piège si l''apprenant ne connaît qu''un seul sens\n- Les registres varient : certains sont familiers (*hold on*), d''autres neutres/formels (*carry out, bring about*) — mal les placer peut sonner déplacé à l''écrit formel"}, {"heading": "Comparaison avec le français", "text": "Comme pour les phrasal verbs de base, le français n''a pas d''équivalent structurel — mais à ce niveau, les phrasal verbs prennent souvent un sens figuré assez éloigné du verbe de base, rendant la déduction encore plus difficile (ex. *turn out* n''a aucun lien évident avec \"tourner\" + \"dehors\")."}, {"heading": "Banque d''exemples", "text": "1. She brought up a good point during the meeting. — Elle a soulevé un bon point pendant la réunion.\n2. I came across your profile online. — Je suis tombé sur ton profil en ligne.\n3. He got away with cheating on the test. — Il s''en est sorti sans être puni pour avoir triché à l''examen.\n4. We had to put off the trip because of the weather. — On a dû reporter le voyage à cause de la météo.\n5. It turned out that she was right all along. — Il s''est avéré qu''elle avait raison depuis le début.\n6. Everything worked out in the end. — Tout s''est bien passé finalement.\n7. The negotiations fell through at the last minute. — Les négociations ont échoué à la dernière minute.\n8. The police are looking into the matter. — La police enquête sur cette affaire.\n9. He set out to become the best in his field. — Il s''est mis en tête de devenir le meilleur dans son domaine.\n10. The effect of the medicine wore off after a few hours. — L''effet du médicament s''est estompé après quelques heures.\n\n**Notions liées** → Fiche 16 (phrasal verbs courants)"}]}'),
  ('B2', 30, 'Nuances modales avancées', '{"sections": [{"heading": "Wish + past perfect (regret du passé)", "text": "*I wish I had studied harder.* (je regrette de ne pas avoir étudié plus — équivalent au third conditional en usage émotionnel)"}, {"heading": "Wish + past simple (souhait présent irréel)", "text": "*I wish I lived closer to my family.* (je ne vis pas près de ma famille, et je le regrette maintenant)"}, {"heading": "If only", "text": "Version plus emphatique/émotionnelle de *wish*, souvent utilisée seule sans proposition principale :\n*If only I had known!* (si seulement j''avais su !)"}, {"heading": "Would rather", "text": "Exprime une préférence :\n- *I would rather stay home.* (+ base verbale, pour soi-même)\n- *I would rather you stayed home.* (+ past simple, quand ça concerne quelqu''un d''autre — attention, forme au passé bien que le sens soit présent)"}, {"heading": "Had better", "text": "Conseil pressant, presque un avertissement :\n*You had better hurry, or you''ll miss the train.* (plus fort que *should*)"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser le present simple après *wish* pour un souhait présent irréel (*\"I wish I live closer\"* est faux, c''est *\"I wish I lived closer\"*)\n- Oublier le past simple après *would rather you* (*\"I would rather you stay\"* est une erreur fréquente, la forme correcte est *\"I would rather you stayed\"*)\n- Confondre *had better* avec *had to* (sens et usage complètement différents malgré la ressemblance)"}, {"heading": "Comparaison avec le français", "text": "Le français utilise \"j''aurais aimé que\" ou \"si seulement\" de façon assez proche conceptuellement, mais la contrainte grammaticale anglaise (temps paradoxalement \"passés\" pour exprimer un sens présent ou futur avec wish/would rather) n''a pas d''équivalent formel en français, qui utilise plus naturellement le conditionnel ou le subjonctif."}, {"heading": "Banque d''exemples", "text": "1. I wish I had studied medicine. — J''aurais aimé étudier la médecine.\n2. I wish I spoke Spanish fluently. — J''aimerais parler espagnol couramment.\n3. If only I had listened to your advice! — Si seulement j''avais écouté ton conseil !\n4. I would rather stay in tonight. — Je préférerais rester à la maison ce soir.\n5. I''d rather you didn''t smoke here. — Je préférerais que tu ne fumes pas ici.\n6. You''d better call her before it''s too late. — Tu ferais mieux de l''appeler avant qu''il ne soit trop tard.\n7. I wish you were here. — J''aimerais que tu sois là.\n8. She wishes she had more free time. — Elle aimerait avoir plus de temps libre.\n9. If only we had more money! — Si seulement on avait plus d''argent !\n10. We''d better leave now if we want to catch the train. — On ferait mieux de partir maintenant si on veut attraper le train.\n\n**Notions liées** → Fiche 19 (conditionnels), Fiche 25 (third conditional)"}]}'),
  ('C1', 31, 'Inversion et emphase', '{"sections": [{"heading": "Inversion après adverbes négatifs en début de phrase", "text": "Quand un adverbe à sens négatif/restrictif ouvre la phrase, l''ordre auxiliaire-sujet s''inverse (comme dans une question) :\n*Never have I seen such a mess.* (jamais je n''ai vu un tel désordre)"}, {"heading": "Adverbes déclencheurs courants", "text": "*never, rarely, seldom, hardly, no sooner... than, not only... but also, little*"}, {"heading": "Structures d''emphase avec inversion", "text": "- *Not only did she win, but she also broke the record.*\n- *Hardly had I arrived when the phone rang.* (à peine étais-je arrivé que...)\n- *No sooner had we sat down than the waiter came.* (à peine assis que...)"}, {"heading": "Registre", "text": "Structure exclusivement écrite/soutenue, jamais utilisée à l''oral courant — signal fort de maîtrise avancée quand employée à bon escient."}, {"heading": "Pièges fréquents des francophones", "text": "- Oublier l''inversion après l''adverbe (l''erreur la plus commune, car le français ne l''exige pas structurellement de la même façon)\n- Confondre avec l''inversion interrogative classique et l''utiliser à mauvais escient dans une phrase non stylistique"}, {"heading": "Comparaison avec le français", "text": "Le français a un équivalent partiel avec \"à peine... que\" qui impose aussi une inversion stylistique (\"à peine étais-je arrivé que...\"), ce qui peut aider à comprendre le mécanisme, mais l''anglais étend cette règle à beaucoup plus d''adverbes et de structures que le français."}, {"heading": "Banque d''exemples", "text": "1. Never have I seen such dedication. — Jamais je n''ai vu un tel dévouement.\n2. Rarely does she complain about anything. — Elle se plaint rarement de quoi que ce soit.\n3. Not only was he late, but he also forgot the documents. — Non seulement il était en retard, mais en plus il a oublié les documents.\n4. Hardly had I sat down when my phone rang. — À peine assis, mon téléphone a sonné.\n5. No sooner had she left than it started to rain. — À peine était-elle partie qu''il a commencé à pleuvoir.\n6. Little did he know what was about to happen. — Il était loin de se douter de ce qui allait arriver.\n7. Seldom have I encountered such rudeness. — Rarement ai-je rencontré une telle impolitesse.\n8. Only after the meeting did I understand the problem. — Ce n''est qu''après la réunion que j''ai compris le problème.\n9. Under no circumstances should you sign this. — Sous aucun prétexte tu ne devrais signer ça.\n10. So surprised was she that she couldn''t speak. — Elle était si surprise qu''elle ne pouvait pas parler.\n\n**Notions liées** → Fiche 33 (phrases clivées)"}]}'),
  ('C1', 32, 'Discours rapporté avancé', '{"sections": [{"heading": "Rapporter conseils, ordres et suggestions", "text": "- Ordre : *tell/order + objet + to + infinitif* → *\"Sit down!\" he said.* → *He told me to sit down.*\n- Conseil : *advise + objet + to + infinitif* → *\"You should rest,\" she said.* → *She advised me to rest.*\n- Suggestion (structure différente, pas de *to*) : *suggest + gérondif* ou *suggest + that + subjonctif* → *\"Let''s go,\" she said.* → *She suggested going. / She suggested that we go.*"}, {"heading": "Verbes introducteurs nuancés", "text": "Au-delà de *say/tell/ask*, le discours rapporté avancé utilise des verbes qui intègrent déjà la nuance de l''énoncé original, évitant les répétitions et les lourdeurs :\n*insist, admit, deny, warn, promise, complain, apologize, threaten, offer*"}, {"heading": "Reformulation stylistique", "text": "- *\"I didn''t take your pen,\" he said.* → *He denied taking my pen.*\n- *\"I''m sorry I''m late,\" she said.* → *She apologized for being late.*\n- *\"If you don''t stop, I''ll call the police,\" he said.* → *He threatened to call the police.*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser systématiquement *say/tell* + *that* même quand un verbe plus précis existerait, ce qui produit un discours rapporté correct mais peu naturel/répétitif à ce niveau\n- Se tromper sur la construction grammaticale propre à chaque verbe (certains + gérondif, d''autres + infinitif, d''autres + *that*)"}, {"heading": "Comparaison avec le français", "text": "Le français dispose aussi de verbes introducteurs nuancés (\"nier, s''excuser, menacer, insister\") mais leur construction grammaticale ne correspond pas terme à terme à l''anglais (ex. \"nier avoir fait\" = *deny + gérondif*, pas d''infinitif comme le laisserait penser le français) — chaque verbe doit être appris avec sa structure propre."}, {"heading": "Banque d''exemples", "text": "1. He denied stealing the money. — Il a nié avoir volé l''argent.\n2. She admitted making a mistake. — Elle a admis avoir fait une erreur.\n3. The teacher warned us not to be late. — Le professeur nous a avertis de ne pas être en retard.\n4. He promised to help me move. — Il a promis de m''aider à déménager.\n5. She apologized for forgetting my birthday. — Elle s''est excusée d''avoir oublié mon anniversaire.\n6. He threatened to quit if things didn''t change. — Il a menacé de démissionner si les choses ne changeaient pas.\n7. She insisted on paying for dinner. — Elle a insisté pour payer le dîner.\n8. He offered to drive us to the airport. — Il a proposé de nous conduire à l''aéroport.\n9. She complained about the noise. — Elle s''est plainte du bruit.\n10. The doctor advised him to rest for a week. — Le médecin lui a conseillé de se reposer pendant une semaine.\n\n**Notions liées** → Fiche 21 (discours rapporté de base)"}]}'),
  ('C1', 33, 'Phrases clivées (cleft sentences)', '{"sections": [{"heading": "Principe", "text": "Les phrases clivées déplacent l''élément à mettre en emphase en tête de phrase via une structure *it is/was... that/who* ou *what... is*, pour souligner ce qui compte vraiment dans l''énoncé.\n\n**Structure *it-cleft***\n*It + be + élément mis en avant + that/who + reste de la phrase*\n- Phrase neutre : *I need more time.*\n- Cleft : *What I need is more time.* (ou : *It''s more time that I need.*)\n\n**Structure *what-cleft***\n*What + proposition + is/was + élément mis en avant*\n- *What surprised me was his reaction.* (ce qui m''a surpris, c''est sa réaction)\n- *What I love about this city is its energy.*"}, {"heading": "Usage", "text": "Registre écrit soigné ou oral emphatique — permet de structurer un argument, un discours, ou de corriger une incompréhension avec force :\n*It wasn''t John who broke the vase, it was Sarah.* (correction emphatique)"}, {"heading": "Pièges fréquents des francophones", "text": "- Ne pas utiliser cette structure du tout par méconnaissance, et se rabattre systématiquement sur l''ordre de phrase neutre (moins naturel dans un contexte où l''emphase est attendue en anglais)\n- Mal accorder le verbe *be* selon le temps de la phrase d''origine (it IS vs it WAS selon le contexte temporel)"}, {"heading": "Comparaison avec le français", "text": "Le français a un équivalent direct et très utilisé : \"c''est... que/qui\" (\"c''est Sarah qui a cassé le vase\") — la structure se transpose presque littéralement en anglais avec *it is... that/who*, ce qui rend cette notion en réalité plus facile à acquérir pour un francophone que pour d''autres nationalités."}, {"heading": "Banque d''exemples", "text": "1. It was Sarah who broke the vase, not John. — C''est Sarah qui a cassé le vase, pas John.\n2. What I need right now is a good night''s sleep. — Ce dont j''ai besoin maintenant, c''est d''une bonne nuit de sommeil.\n3. It''s the way he talks to people that annoys me. — C''est sa façon de parler aux gens qui m''agace.\n4. What surprised everyone was how calm she stayed. — Ce qui a surpris tout le monde, c''est à quel point elle est restée calme.\n5. It was in 2015 that we first met. — C''est en 2015 qu''on s''est rencontrés pour la première fois.\n6. What matters most is your health. — Ce qui compte le plus, c''est ta santé.\n7. It''s not the money that motivates her, it''s the challenge. — Ce n''est pas l''argent qui la motive, c''est le défi.\n8. What I love about travelling is meeting new people. — Ce que j''aime dans les voyages, c''est rencontrer de nouvelles personnes.\n9. It was my grandmother who taught me to cook. — C''est ma grand-mère qui m''a appris à cuisiner.\n10. What we need to discuss is the budget for next year. — Ce dont on doit discuter, c''est le budget pour l''année prochaine.\n\n**Notions liées** → Fiche 31 (inversion et emphase), Fiche 22 (propositions relatives)"}]}'),
  ('C1', 34, 'Expressions idiomatiques', '{"sections": [{"heading": "Principe", "text": "Les expressions idiomatiques ont un sens figuré non déductible des mots pris séparément. Essentielles pour sonner naturel et comprendre l''anglais authentique (films, conversations, presse)."}, {"heading": "20 expressions idiomatiques courantes par thème", "text": "*Effort et réussite*\n- *hit the nail on the head* — voir juste, mettre le doigt dessus\n- *once in a blue moon* — très rarement\n- *piece of cake* — un jeu d''enfant\n- *the ball is in your court* — c''est à toi de décider/agir\n\n*Difficulté et échec*\n- *break the ice* — briser la glace\n- *bite the bullet* — se résigner, prendre son courage à deux mains\n- *under the weather* — patraque, pas en forme\n- *back to the drawing board* — retour à la case départ\n\n*Argent*\n- *cost an arm and a leg* — coûter les yeux de la tête\n- *break even* — rentrer dans ses frais\n- *save for a rainy day* — mettre de côté pour les coups durs\n\n*Communication et relations*\n- *beat around the bush* — tourner autour du pot\n- *let the cat out of the bag* — vendre la mèche\n- *on the same page* — sur la même longueur d''onde\n- *behind someone''s back* — dans le dos de quelqu''un\n\n*Temps et opportunité*\n- *once in a while* — de temps en temps\n- *in the nick of time* — juste à temps\n- *out of the blue* — de manière inattendue\n- *time flies* — le temps passe vite\n- *better late than never* — mieux vaut tard que jamais"}, {"heading": "Pièges fréquents des francophones", "text": "- Chercher une traduction littérale au lieu de mémoriser l''expression comme un tout figé\n- Employer l''expression dans un registre inadapté (certaines sont familières, d''autres passent bien à l''écrit)"}, {"heading": "Comparaison avec le français", "text": "Le français a ses propres idiomes souvent totalement différents en image (\"coûter les yeux de la tête\" vs \"cost an arm and a leg\" — parties du corps différentes pour la même idée), preuve qu''une traduction terme à terme ne fonctionne jamais pour ce type d''expression."}, {"heading": "Banque d''exemples", "text": "1. You hit the nail on the head with that comment. — Tu as vu juste avec cette remarque.\n2. We only see each other once in a blue moon. — On se voit très rarement.\n3. Don''t worry, the exam was a piece of cake. — T''inquiète, l''examen était un jeu d''enfant.\n4. I think it''s time to bite the bullet and tell her. — Je pense qu''il est temps de se lancer et de lui dire.\n5. This new phone cost me an arm and a leg. — Ce nouveau téléphone m''a coûté les yeux de la tête.\n6. Stop beating around the bush and tell me what happened. — Arrête de tourner autour du pot et dis-moi ce qui s''est passé.\n7. I feel a bit under the weather today. — Je ne me sens pas très bien aujourd''hui.\n8. He let the cat out of the bag about the surprise party. — Il a vendu la mèche à propos de la fête surprise.\n9. We arrived just in the nick of time. — On est arrivés juste à temps.\n10. Her call came completely out of the blue. — Son appel est arrivé de manière totalement inattendue.\n\n**Notions liées** → Fiche 16 et 29 (phrasal verbs)"}]}'),
  ('C1', 35, 'Registres de langue', '{"sections": [{"heading": "Formel vs informel — vocabulaire", "text": "| Informel | Formel/neutre |\n|---|---|\n| get | receive / obtain |\n| a lot of | a great deal of / numerous |\n| find out | discover / determine |\n| kids | children |\n| guy | man / individual |\n| buy | purchase |\n| ask for | request |\n| but | however |\n| also | in addition / furthermore |"}, {"heading": "Anglais professionnel — emails et réunions", "text": "- Ouverture d''email formel : *I am writing to inquire about... / Further to our conversation...*\n- Formule de politesse : *I would be grateful if you could... / Would you mind + gérondif...?*\n- Clôture : *I look forward to hearing from you. / Please do not hesitate to contact me.*\n- Réunion : *Let''s move on to the next point. / Could you elaborate on that? / I''d like to raise a concern about...*"}, {"heading": "Familier / oral décontracté", "text": "- Contractions renforcées à l''oral : *gonna (going to), wanna (want to), gotta (got to)*\n- Interjections de remplissage : *like, you know, I mean, basically*\n- Argot léger courant : *stuff, guys, awesome, totally*"}, {"heading": "Pièges fréquents des francophones", "text": "- Utiliser un registre familier appris via les séries/réseaux sociaux dans un contexte professionnel écrit (mail à un supérieur avec \"gonna\", \"guys\")\n- À l''inverse, sonner too formel/rigide à l''oral décontracté en réutilisant du vocabulaire académique appris en cours"}, {"heading": "Comparaison avec le français", "text": "Le français a aussi une distinction tu/vous et des registres marqués lexicalement, ce qui aide à comprendre le principe général — mais l''anglais n''ayant pas d''équivalent au tu/vous, toute la distinction de politesse et de registre passe uniquement par le choix du vocabulaire et des tournures, ce qui demande un apprentissage plus explicite pour un francophone habitué au marqueur grammatical du vouvoiement."}, {"heading": "Banque d''exemples", "text": "1. I am writing to inquire about the position advertised on your website. — Je vous écris pour me renseigner sur le poste annoncé sur votre site.\n2. Would you mind sending me the report by tomorrow? — Cela vous dérangerait-il de m''envoyer le rapport d''ici demain ?\n3. I look forward to hearing from you. — Dans l''attente de votre réponse.\n4. Could you elaborate on that point, please? — Pourriez-vous développer ce point, s''il vous plaît ?\n5. I''d like to raise a concern about the timeline. — J''aimerais soulever une préoccupation concernant le calendrier.\n6. We received numerous applications for this role. — Nous avons reçu de nombreuses candidatures pour ce poste.\n7. I''m gonna grab a coffee, you want one? — Je vais chercher un café, t''en veux un ? (informel)\n8. That party was totally awesome. — Cette fête était vraiment géniale. (informel)\n9. Please do not hesitate to contact me should you have any questions. — N''hésitez pas à me contacter si vous avez des questions.\n10. Honestly, I mean, it''s just not worth it, you know? — Honnêtement, enfin, ça vaut juste pas le coup, tu vois ? (très informel, oral)\n\n**Notions liées** → Fiche 28 (connecteurs avancés)"}]}'),
  ('C1', 36, 'Fluidité conversationnelle', '{"sections": [{"heading": "Connecteurs et marqueurs à l''oral", "text": "Servent à structurer la pensée en temps réel, gagner du temps, nuancer :\n- *Well, ... / So, ... / Actually, ... / I mean, ... / Anyway, ...*\n- Pour nuancer une opinion : *To be honest... / As far as I''m concerned... / If you ask me...*\n- Pour temporiser en cherchant ses mots : *Let me think... / How can I put this... / What''s the word...*"}, {"heading": "Gérer un débat ou une négociation", "text": "- Introduire un contre-argument : *I see your point, but... / That''s true, however... / I understand, although...*\n- Renforcer un argument : *The thing is... / What''s more... / Not to mention that...*\n- Trouver un compromis : *Maybe we could meet halfway. / What if we tried a different approach?*\n- Conclure/trancher : *At the end of the day... / When it comes down to it...*"}, {"heading": "Hésitations naturelles (à ne pas éviter à l''oral)", "text": "Contrairement à l''écrit où elles seraient bannies, des hésitations légères rendent l''oral plus naturel et donnent le temps de formuler sa pensée : *um, well, you know, kind of, sort of*"}, {"heading": "Pièges fréquents des francophones", "text": "- Parler un anglais \"trop propre\", sans aucun marqueur de discours, ce qui sonne artificiel/scolaire à l''oral — les natifs utilisent constamment ces connecteurs\n- Traduire littéralement les hésitations françaises (\"euh\" devient \"euh\" et non \"um/uh\", réflexe à corriger)"}, {"heading": "Comparaison avec le français", "text": "Le français a ses propres marqueurs oraux équivalents (\"enfin, bon, du coup, en fait, tu vois\") qui remplissent exactement la même fonction — le transfert conceptuel est facile, la difficulté est uniquement lexicale (apprendre les bons équivalents anglais et ne pas hésiter à les utiliser, contrairement au réflexe scolaire qui pousse à parler \"trop parfait\")."}, {"heading": "Banque d''exemples", "text": "1. Well, I think we should reconsider the plan. — Bon, je pense qu''on devrait reconsidérer le plan.\n2. To be honest, I''m not sure this is a good idea. — Honnêtement, je ne suis pas sûr que ce soit une bonne idée.\n3. I see your point, but I think there''s another way to look at it. — Je comprends ton point de vue, mais je pense qu''on peut voir ça autrement.\n4. The thing is, we don''t have enough time. — Le truc, c''est qu''on n''a pas assez de temps.\n5. Maybe we could meet halfway on this. — On pourrait peut-être trouver un compromis là-dessus.\n6. What if we tried a completely different approach? — Et si on essayait une approche complètement différente ?\n7. At the end of the day, it''s your decision. — En fin de compte, c''est ta décision.\n8. Let me think... how can I put this... — Laisse-moi réfléchir... comment dire ça...\n9. Not to mention that it would save us a lot of money. — Sans compter que ça nous ferait économiser beaucoup d''argent.\n10. If you ask me, we should just go for it. — Si tu veux mon avis, on devrait juste se lancer.\n\n**Notions liées** → Fiche 28 (connecteurs de discours avancés)"}]}')
) as v(cecr_level, position, title, content);
